<?php
ini_set('display_errors','0');header('Content-Type: application/json; charset=utf-8');require_once __DIR__ . '/_vault_helpers.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;}$db=vault_db();$actor=vault_require_auth();vault_require_csrf($_POST);vault_require_verified();$folder=(int)($_POST['folder_id']??0);if(!vault_folder_owned($db,$folder,$actor)){ApiResponse::validation(['folder_id'=>'Folder not found.']);exit;}if(empty($_FILES['file']['tmp_name'])){ApiResponse::validation(['file'=>'File required.']);exit;}$file=$_FILES['file'];$size=(int)$file['size'];$original=(string)$file['name'];$ext=strtolower(pathinfo($original,PATHINFO_EXTENSION));$mime=(string)($file['type']??'application/octet-stream');if($size<=0||$size>VAULT_MAX_FILE_SIZE){ApiResponse::validation(['file'=>'Invalid file size.']);exit;}if(!in_array($ext,VAULT_ALLOWED_EXTENSIONS,true)||!in_array($mime,VAULT_ALLOWED_MIME_TYPES,true)){ApiResponse::validation(['file'=>'Invalid vault file type.']);exit;}$plain=@file_get_contents($file['tmp_name']);if($plain===false){throw new RuntimeException('Upload read failed.');}$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',vault_derived_key($actor),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false||strlen($tag)!==16){throw new RuntimeException('Encryption failed.');}$name=vault_safe_name($original);if($name==='Untitled')$name=vault_safe_name(pathinfo($original,PATHINFO_FILENAME));$encryptedName='db_'.bin2hex(random_bytes(24)).'.vault';$s=$db->prepare("INSERT INTO vault_documents(owner_id,folder_id,display_name,original_filename,encrypted_filename,encrypted_blob,encryption_version,mime_type,file_size,plaintext_sha256,ciphertext_sha256,iv,auth_tag) VALUES(:owner,:folder,:display,:original,:encrypted,:blob,'aes-256-gcm-db-v1',:mime,:size,:plain_hash,:cipher_hash,:iv,:tag)");$s->bindValue(':owner',$actor,PDO::PARAM_INT);$s->bindValue(':folder',$folder?:null,$folder?PDO::PARAM_INT:PDO::PARAM_NULL);$s->bindValue(':display',$name);$s->bindValue(':original',$original);$s->bindValue(':encrypted',$encryptedName);$s->bindValue(':blob',$cipher,PDO::PARAM_LOB);$s->bindValue(':mime',$mime);$s->bindValue(':size',$size,PDO::PARAM_INT);$s->bindValue(':plain_hash',hash('sha256',$plain));$s->bindValue(':cipher_hash',hash('sha256',$cipher));$s->bindValue(':iv',$iv,PDO::PARAM_LOB);$s->bindValue(':tag',$tag,PDO::PARAM_LOB);$s->execute();$id=(int)$db->lastInsertId();vault_log($db,$actor,$actor,$id,'upload');ApiResponse::success(['document_id'=>$id],'Vault document uploaded.',201);}catch(Throwable $e){Logger::error('Vault upload failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to upload vault document.');}
